import React from "react";
import PredictForm from "./PredictForm";

function App() {
  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h1 style={styles.title}>
          Company Growth Analytics System
        </h1>

        <p style={styles.subtitle}>
          Enter company details below and select a model to predict growth.
        </p>

        <PredictForm />
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "#f4f6f9",
    padding: "20px"
  },
  card: {
    width: "100%",
    maxWidth: "600px",
    backgroundColor: "#ffffff",
    padding: "30px",
    borderRadius: "12px",
    boxShadow: "0 8px 20px rgba(0,0,0,0.08)"
  },
  title: {
    textAlign: "center",
    color: "#2c3e50",
    marginBottom: "10px"
  },
  subtitle: {
    textAlign: "center",
    color: "#7f8c8d",
    marginBottom: "25px"
  }
};

export default App;
